 return `<div class="job-description" id="prompt-${esc(j.id)}"><span class="job-description-text">${esc(more?text.slice(0,limit).trimEnd():text)}</span>${text.length>130?`<span class="prompt-tail">${more?'<span aria-hidden="true">…</span>':''}<button class="text-control" data-action="full-prompt" data-job="${j.id}" aria-controls="prompt-${esc(j.id)}" aria-expanded="${limit>130}">${more?(limit>130?'继续展开':'展开描述'):'收起描述'}</button></span>`:''}</div>`;
