function jobHTML(j,index){return `<article class="job-row" id="job-${j.id}" data-job-id="${j.id}">${jobReferences(j)}<div class="job-top"><span class="job-order">${String(index+1).padStart(2,'0')}</span><div class="job-prompt">${j.real&&workflows.find(w=>w.id===j.snapshot.workflowId)?.catalogOnly&&!workflows.find(w=>w.id===j.snapshot.workflowId)?.interface?.texts.some(t=>t.role==='prompt')?'':promptMarkup(j)}<div class="job-meta">${jobMeta(j)} ${B('参数','job-settings','text-control',`data-job="${j.id}"`)} <span class="demo-mark">${j.real?'真实生成':j.status==='done'?'演示结果':'演示任务'}</span></div></div></div><div class="job-body">${j.status==='done'?`<div class="output-grid count-${j.outputs.length}">${j.outputs.filter(o=>!o.removedAt).map((o,i)=>outputHTML(o,j,i)).join('')||'<p class="removed-job-note">本次作品已移除，可在「我的作品 → 已移除」恢复。</p>'}</div>`:progressHTML(j)}</div><div class="job-actions">${j.status==='done'?`${B(I('expand')+'重新编辑','reedit','small-button',`data-job="${j.id}"`)}${j.real&&workflows.find(w=>w.id===j.snapshot.workflowId)?.catalogOnly&&!workflows.find(w=>w.id===j.snapshot.workflowId)?.interface?.controls.some(f=>f.kind==='seed')?'':B(I('history')+(j.real?'再抽一版':'再抽一版 · 演示'),'rerun','small-button',`data-job="${j.id}"`)}${originalCompareAction(j)}${j.outputs.filter(o=>!o.removedAt).length>1?B('并排对比','batch-compare','small-button',`data-job="${j.id}"`):''}<span>完成用时 ${formatTime((j.ended||Date.now())-j.started)}</span>`:''}</div></article>`;}
function feedHTML(s){return s.jobs.map(jobHTML).join('');}
function refreshFeed(scroll=false){const feed=$('#result-feed');if(!feed)return;const nearEnd=feed.scrollHeight-feed.scrollTop-feed.clientHeight<100,stream=feed.querySelector('.result-stream');const nodes=new Map([...stream.children].map(el=>[el.dataset.jobId,el]));for(const [index,j] of active().jobs.entries()){const html=jobHTML(j,index),old=nodes.get(j.id);nodes.delete(j.id);if(old){if(old._markup===html)continue;const template=document.createElement('template');template.innerHTML=html;const fresh=template.content.firstElementChild;fresh._markup=html;old.replaceWith(fresh);}else{stream.insertAdjacentHTML('beforeend',html);stream.lastElementChild._markup=html;}}for(const el of nodes.values())el.remove();const total=feed.querySelector(':scope > header > span');if(total)total.textContent=active().jobs.length+' 次创作';const empty=$('#wf-empty');if(empty)empty.hidden=!!active().jobs.length;syncSelection();feed.dataset.followLatest=String(scroll||nearEnd);if(scroll||nearEnd)scrollFeedToEnd(feed);if(scroll&&matchMedia('(max-width:720px)').matches)feed.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});updateFeedPosition(feed);}
function refreshComposer(){
 const holder=$('#composer-slot');if(!holder)return;
 const old=document.activeElement,focused=holder.contains(old),focusId=old?.id,focusText=old?.dataset?.catalogText,focusApi=old?.dataset?.catalogApi,focusApiField=old?.dataset?.apiField,start=old?.selectionStart,end=old?.selectionEnd;
 const scroll=holder.querySelector('.wf-editor-scroll')?.scrollTop||0,open=[...holder.querySelectorAll('details')].map(e=>e.open);
 holder.innerHTML=workflow(active())?workflowEditor():composer();holder.querySelectorAll('details').forEach((e,i)=>{e.open=open[i]||false;});
 observeComposer();setupWorkflowMask();fitCatalogSelector();const scroller=holder.querySelector('.wf-editor-scroll');if(scroller)scroller.scrollTop=scroll;
 if(focused){const next=focusId?document.getElementById(focusId):focusApi?[...holder.querySelectorAll('[data-catalog-api]')].find(e=>e.dataset.catalogApi===focusApi&&e.dataset.apiField===focusApiField):[...holder.querySelectorAll('[data-catalog-text]')].find(e=>e.dataset.catalogText===focusText);if(next){next.focus({preventScroll:true});if(start!==null&&start!==undefined&&['text','search','url','tel','password'].includes(next.type)||next?.tagName==='TEXTAREA')next.setSelectionRange(start,end);}}
}
let clearMentions=()=>{};
let clearPromptRail=()=>{};
let clearReferenceShelf=()=>{};
function installPromptRail(){
 clearPromptRail();const input=$('#prompt');if(!input)return;
 let row=input.closest('.writing-row');
 if(!row){row=document.createElement('div');row.className='writing-row';input.before(row);const area=document.createElement('div');area.className='writing-area';row.append(area);area.append(input);}
 row.querySelector('.expand-writing')?.remove();
 const rail=document.createElement('div');rail.className='prompt-rail';
 const scroll=document.createElement('input');scroll.type='range';scroll.min='0';scroll.step='1';scroll.value='0';scroll.setAttribute('aria-label','滚动提示词');scroll.setAttribute('aria-orientation','vertical');rail.append(scroll);row.append(rail);
 const sync=()=>{const max=Math.max(0,input.scrollHeight-input.clientHeight),overflow=max>1;rail.hidden=!overflow;row.classList.toggle('has-prompt-overflow',overflow);scroll.max=String(max||1);scroll.value=String(input.scrollTop);scroll.disabled=!overflow;};
 scroll.addEventListener('input',()=>{input.scrollTop=Number(scroll.value);});input.addEventListener('scroll',sync);input.addEventListener('input',sync);
 const observer=new ResizeObserver(sync);observer.observe(input);sync();
 clearPromptRail=()=>{observer.disconnect();input.removeEventListener('scroll',sync);input.removeEventListener('input',sync);rail.remove();};
}
function observeComposer(){const w=workflow(active()),holderRoot=$('#composer-slot');if(w?.catalogOnly&&holderRoot){syncCameraGuide(holderRoot,w,active().draft);syncOutpaintGuide(holderRoot,w,active().draft);}closeApiMentionMenu();enhanceSourcePreview();clearMentions();clearReferenceShelf();clearReferenceShelf=installReferenceShelf($('.api-reference-shelf'));installPromptRail();syncComposerExpansion();clearMentions=mountMentions($('#prompt'),()=>visibleRefs());autosizeApiPrompt();resizeObserver?.disconnect();const holder=$('#composer-slot');if(holder){resizeObserver=new ResizeObserver(()=>document.documentElement.style.setProperty('--dock-height',holder.offsetHeight+'px'));resizeObserver.observe(holder);}feedResizeObserver?.disconnect();const feed=$('.workflow-results#result-feed');if(feed){feedResizeObserver=new ResizeObserver(()=>{if(feed.dataset.followLatest==='true')scrollFeedToEnd(feed);updateFeedPosition(feed);});feedResizeObserver.observe(feed);feedResizeObserver.observe(feed.querySelector('.result-stream'));}}
function compactDescription(w){return ({'h3-reference':'参考图生成有声视频，最多 9 张图。','bernini-edit':'修改人物或场景，保留原片动作与声音。'})[w.id]||w.desc?.slice(0,46)||'';}
function workflowCard(w,customCover=true){return `<a class="workflow-card" href="#workflow/${w.id}" aria-describedby="description-${w.id}"><div class="workflow-cover task-cover">${customCover?taskCover(w,allOutputs()):`<img src="assets/${esc(w.cover)}" alt="" loading="lazy">`}</div><span class="wf-card-status">${w.catalogPendingApi?'待 API 验证':w.catalogConnected||w.live?'已接入':w.catalogOnly?'界面设计':'交互演示'}</span><div class="workflow-info"><h2>${esc(w.name)}</h2><p id="description-${w.id}">${esc(compactDescription(w))}</p></div></a>`;}
function gallery(){
 const q=state.query.trim().toLowerCase(),match=w=>!q||(w.name+' '+w.desc+' '+w.category+' '+(w.aliases||[]).join(' ')).toLowerCase().includes(q);
 const groups=state.category==='全部'&&!q?localCatalog.categories.map(cat=>{const family=workflows.filter(w=>w.category===cat),ids=new Set(family.map(w=>w.id)),history=allOutputs().filter(({j})=>j.real&&ids.has(j.snapshot.workflowId)&&j.status==='done').at(-1),w=family.find(w=>w.id===history?.j.snapshot.workflowId)||family[0];return w?`<a class="workflow-card workflow-family" href="#workflows" data-category="${esc(cat)}"><div class="family-cover task-cover">${taskCover(w,allOutputs(),true)}</div><div class="family-meta"><span class="family-symbol">${I(cat.includes('视频')||cat.includes('舞蹈')||cat.includes('数字人')?'video':cat.includes('图')?'image':cat.includes('提示词')?'spark':'folder')}</span><span>${family.length} 个工具</span></div><div class="workflow-info"><h2>${esc(cat)}</h2><p>${esc(categoryDescription(cat))}</p></div><span class="family-open" aria-hidden="true">${I('arrow')}</span></a>`:'';}).join(''):'';
 const list=workflows.filter(w=>(w.catalogOnly||w.live)&&(state.category==='全部'||state.category==='已接入'&&(w.live||w.catalogConnected&&!w.catalogPendingApi)||w.category===state.category)&&match(w));
 return `<section class="library-page workflow-page"><header class="library-head compact-head"><h1>创作工具</h1><label class="searchbox">${I('search')}<input id="workflow-search" aria-label="搜索创作工具" placeholder="搜索名称、模型或用途" value="${esc(state.query)}"></label></header><div class="category-tabs catalog-categories">${categories.map(c=>`<button class="category ${c===state.category?'active':''}" data-category="${c}" aria-pressed="${c===state.category}">${c}</button>`).join('')}</div><div class="workflow-grid">${groups||list.map(w=>workflowCard(w)).join('')||'<p>没有匹配的工作流</p>'}</div><details class="catalog-inventory"><summary>本地清单：${localCatalog.workflows.length} 个去重工作流 · ${localCatalog.missing.length} 个不可用文件</summary><p>扫描 ${localCatalog.sourceCount||0} 份有效图文件，合并 ${localCatalog.duplicateCount||0} 份相同结构与参数的副本。API 与 UI 格式、参数不同的版本保留。</p>${localCatalog.missing.map(x=>`<p>${esc(x.name)}：${esc(x.reason)}</p>`).join('')}</details></section>`;
}

function studioHome(){return `<div class="studio-home"><header class="studio-home-head"><span>映序创作台</span><h1>从想法到作品，选一个起点。</h1></header><div class="studio-paths"><a href="#create"><span>${I('spark')}</span><strong>自由创作</strong><small>沿用熟悉的图像与视频创作界面</small>${I('arrow')}</a><a href="#workflows"><span>${I('grid')}</span><strong>创作工具</strong><small>按任务选择，素材与参数在同一处完成</small>${I('arrow')}</a></div>${discoveries()}<div class="studio-home-more"><a href="#inspiration">进入灵感库 · 查看创作方式 ${I('arrow')}</a></div></div>`;}
