function inspirationContent(){const q=workspace.inspirationQuery.trim().toLowerCase(),type=workspace.inspirationFilter,published=allOutputs().filter(({o,j,s})=>o.published&&!o.removedAt&&(type==='全部'||o.type===(type==='图像'?'image':'video'))&&matchesWork({o,j,s},q,'all',Date.now(),workflows)),examples=featured.map((f,i)=>({f,i})).filter(({f})=>type!=='视频'&&(!q||(f.title+' '+f.tag+' '+f.prompt).toLowerCase().includes(q)));return `<div class="inspiration-grid">${published.map(({o,j})=>`<button class="inspiration-card" data-action="published" data-id="${o.id}">${o.type==='video'?`<video src="${esc(o.src)}" muted playsinline preload="metadata"></video>`:`<img src="${esc(o.src)}" alt="" loading="lazy">`}<span><strong>${esc(j.snapshot.prompt.slice(0,24)||'我的作品')}</strong><small class="inspiration-caption">${esc(j.snapshot.prompt.slice(0,55))}</small></span></button>`).join('')}${examples.map(({f,i})=>`<button class="inspiration-card" data-action="featured" data-index="${i}"><img src="assets/${f.cover}" alt="${esc(f.title)}" loading="lazy"><span><strong>${esc(f.title)}</strong><small class="inspiration-caption">${esc(f.tag)}</small></span></button>`).join('')}</div>${!published.length&&!examples.length?'<div class="useful-empty"><h2>没有匹配的灵感</h2><p>换个关键词或选择其他类型。</p></div>':''}`;}
function videoReferencePanel(w,d){const labels={'video-edit':'修改参考图','video-background':'新背景参考图','video-character':'新角色参考图','video-restyle':'风格参考图'};if(!labels[w.id])return '';const images=d.refs.filter(r=>r.kind==='image');return `<section class="wf-section wf-image-reference workflow-visible-references"><div class="wf-section-title"><strong>${labels[w.id]}</strong><span>可选</span></div><div class="reference-strip">${images.map(r=>`<div class="ref-tile"><button data-preview-ref="${r.id}" aria-label="查看${r.id}" title="${esc(r.name)}"><img src="${esc(r.src)}" alt=""><span>${r.id}</span></button><button class="remove-ref" data-remove="${r.id}" aria-label="移除${r.id}">${I('close')}</button></div>`).join('')}<button class="upload-tile glass compact" data-action="open-image-assets" aria-label="选择${labels[w.id]}">${I('plus')}<span>添加图片</span></button></div></section>`;}
