function workflowEditor(){const s=active(),w=workflow(s),d=s.draft;if(w.catalogOnly)return catalogEditor(w,d).replace('<div class="wf-editor-scroll">',workflowEditorHead()+'<div class="wf-editor-scroll">');if(w.live){d.type='video';d.mode='全能参考';return `<section class="wf-editor" aria-label="${esc(w.name)}编辑区">${workflowEditorHead()}${liveWorkflowEditor({w,d,values:liveSettings(d,w),refs:refsMarkup(d,videoEditWorkflows.has(w.id)?'image':undefined),error:issueHTML(d),upload:uploadControl(d),imageUpload:videoEditWorkflows.has(w.id)?`<button class="upload-tile glass compact" data-action="open-image-assets" aria-label="选择参考图片">${I('plus')}<span>参考图片</span></button>`:uploadControl(d),sourceUpload:videoEditWorkflows.has(w.id)?`<button class="upload-tile glass compact" data-action="replace-source" aria-label="选择原视频">${I('video')}<span>原视频</span></button>`:uploadControl(d),submitting:s.liveSubmitting})}</section>`;}return `<section class="wf-editor wf-demo-editor" aria-label="${esc(w.name)}编辑区">${workflowEditorHead()}<div class="wf-editor-scroll"><div class="wf-editor-inner">${w.id==='image-edit'?`<section class="wf-section"><div class="wf-section-title"><strong>标记修改区域</strong><span>交互演示</span></div><div class="wf-mask-host"><img src="${esc(d.refs.find(r=>r.kind==='image')?.src||'assets/'+w.cover)}" alt="待修改画面"><canvas id="wf-mask" aria-label="在图片上绘制修改区域"></canvas></div><div class="wf-mask-tools"><button data-mask-tool="brush" aria-pressed="true">画笔</button><button data-mask-tool="erase" aria-pressed="false">擦除</button><button data-mask-tool="clear">清空</button><label>粗细 <input id="wf-brush-size" type="range" min="4" max="80" value="24" aria-label="画笔和擦除粗细"><output id="wf-brush-value">24 px</output></label></div></section>`:''}${demoWorkflowMedia({w,d})}${videoReferencePanel(w,d)}${composer().replace(/<button class="button primary generate"[\s\S]*?<\/button>/,'')}</div></div><footer class="wf-editor-footer"><span>交互演示 · 不扣费</span><button class="button primary generate" data-action="generate">${I('spark')}演示生成 ${I('arrow')}</button></footer></section>`;}
function workflowCreation(){
 const s=active(),w=workflow(s),video=w.output==='video'||w.live||w.category.includes('视频')||videoEditWorkflows.has(w.id);
 return `<div class="workflow-detail ${videoEditWorkflows.has(w.id)?'video-edit':''}" data-workflow-output="${video?'video':'image'}"><div class="workflow-layout"><div class="wf-composer-slot" id="composer-slot">${workflowEditor()}</div><section class="workflow-results" id="result-feed" aria-label="生成作品" tabindex="0"><header><strong>生成作品</strong><span>${s.jobs.length} 次创作</span><div id="compare-tray" class="compare-tray" hidden></div></header><div id="wf-empty" class="wf-results-empty" ${s.jobs.length?'hidden':''}>${w.catalogOnly?catalogOverview(w):`<div class="wf-empty-art" aria-hidden="true">${I(video?'video':'image')}</div><strong>等待第一版作品</strong><p>填写描述与素材，生成后可查看、下载，或拖回工作区用作参考。</p>`}</div><div class="result-stream">${feedHTML(s)}</div><button type="button" class="feed-bottom" data-action="feed-bottom" hidden>${I('down')}回到最新作品</button></section></div></div>`;
}
const trimTime=n=>`${Number(n).toFixed(2).replace(/\.?0+$/,'')} 秒`;
const snapTrim=n=>Math.round(Number(n)*100)/100;
function updateWorkflowTrim(input){const d=active().draft,w=liveWorkflow();if(!videoEditWorkflows.has(w?.id))return;const v=liveSettings(d,w),startInput=$('[data-wf-trim="start"]'),endInput=$('[data-wf-trim="end"]');if(!startInput||!endInput)return;const max=Number(startInput.max),changed=input?.dataset.wfTrim;let start=snapTrim(startInput.value),end=snapTrim(endInput.value);if(changed==='start'){start=Math.min(start,end-1);if(end-start>15)end=start+15;}if(changed==='end'){end=Math.max(end,start+1);if(end-start>15)start=end-15;}const minimumSpan=.01;start=snapTrim(Math.max(0,Math.min(start,max-minimumSpan)));end=snapTrim(Math.min(max,Math.max(start+minimumSpan,end)));startInput.value=start;endInput.value=end;if(w.fields?.some(f=>f.key==='trim_start'))v.trim_start=start;if(w.fields?.some(f=>f.key==='duration'))v.duration=snapTrim(end-start);d.trimStart=start;d.trimEnd=end;const trim=startInput.closest('.wf-trim');trim?.style.setProperty('--trim-start',start/max*100+'%');trim?.style.setProperty('--trim-end',end/max*100+'%');$('[data-trim-output="start"]').textContent=trimTime(start);$('[data-trim-output="end"]').textContent=trimTime(end);const video=$('#wf-source-video');if(video&&changed){video.pause();video.currentTime=changed==='start'?start:Math.max(start,end-.01);}scheduleSave();}
function setupWorkflowMask(){const canvas=$('#wf-mask');if(!canvas)return;const box=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;canvas.width=Math.round(box.width*dpr);canvas.height=Math.round(box.height*dpr);const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);let drawing=false,mode='brush';const point=e=>{const r=canvas.getBoundingClientRect();return[e.clientX-r.left,e.clientY-r.top]};canvas.onpointerdown=e=>{drawing=true;canvas.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...point(e))};canvas.onpointermove=e=>{if(!drawing)return;ctx.globalCompositeOperation=mode==='erase'?'destination-out':'source-over';ctx.strokeStyle='#bc9ae7a8';ctx.lineWidth=Number($('#wf-brush-size')?.value)||24;ctx.lineCap='round';ctx.lineJoin='round';ctx.lineTo(...point(e));ctx.stroke()};canvas.onpointerup=canvas.onpointercancel=()=>drawing=false;$$('[data-mask-tool]').forEach(b=>b.onclick=()=>{if(b.dataset.maskTool==='clear'){ctx.clearRect(0,0,box.width,box.height);return;}mode=b.dataset.maskTool;$$('[data-mask-tool]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});}
async function usePublished(id){const found=findOutput(id);if(!found)return;const d=cloneDraft(found.j.snapshot),scope=d.workflowId?'wf:'+d.workflowId:'model',s=makeSession(scope,d.type);s.draft={...renumberDraftReferences(d),error:null};dialog.close();location.hash=d.workflowId?'workflow/'+d.workflowId:'create';render();await saveWorkspace();$('#prompt')?.focus();}
function useFeatured(index){const f=featured[index];if(!f)return;const s=makeSession('model','image');Object.assign(s.draft,{prompt:f.prompt,ratio:'16:9',quality:'2K',count:1});dialog.close();location.hash='create';render();$('#prompt')?.focus();scheduleSave();}
function findOutput(id){for(const s of state.sessions)for(const j of s.jobs){const o=j.outputs.find(o=>o.id===id);if(o)return{o,j,s};}return null;}
function findJob(id){for(const s of state.sessions){const j=s.jobs.find(j=>j.id===id);if(j)return{j,s};}return null;}
function allOutputs(){return state.sessions.flatMap(s=>s.jobs.flatMap(j=>j.outputs.map(o=>({o,j,s}))));}
function settings(){return `<section class="library-page settings-page"><header class="library-head"><h1>偏好设置</h1></header><div class="settings-panel glass"><h2>品牌标志</h2><p>替换 Logo，不改变首页影片或鼠标跟随效果。</p><div class="logo-lab">${logo()}<div>${B('流线标志','logo-original')}${B('宽字标','logo-wide')}${B('纯文字','logo-text')}<label class="brand-upload control small-button">上传 Logo<input type="file" id="logo-upload" accept="image/svg+xml,image/png,image/webp,image/jpeg" aria-label="上传 Logo"></label></div></div></div><div class="settings-panel glass"><h2>动态效果</h2><p>跟随系统的“减少动态效果”设置；触屏设备的首页按钮固定居中。</p><a class="control small-button" href="index.html">查看首页 ${I('arrow')}</a></div></section>`;}
function render(){closeApiMentionMenu();shell.inert=false;closePanel();dialog.close();cleanup.forEach(f=>f());cleanup=[];document.body.classList.remove('nav-open');if(!production){landing();return;}resolveSession();document.body.className='production';sidebar();const r=route(),wf=workflow(active()),detail=r.name==='workflow'||r.name==='session'&&!!wf;if(r.name==='session'&&r.kind==='ref'&&!wf)active().apiRefsPinned=true;main.innerHTML=r.name==='home'?studioHome():r.name==='inspiration'?inspiration():r.name==='workflows'?gallery():r.name==='library'?library():r.name==='assets'?assetLibrary():r.name==='settings'?settings():detail?workflowCreation():creation();document.title=(r.name==='home'?'首页':r.name==='inspiration'?'灵感库':r.name==='workflows'?'创作工具':r.name==='library'?'我的作品':r.name==='assets'?'素材库':r.name==='settings'?'偏好设置':detail?taskOperation(wf).title:'自由创作')+' · 映序';observeComposer();if(r.name==='library')syncWorkSelection();else syncSelection();if($('#result-feed')&&active().jobs.length)scrollFeedToEnd($('#result-feed'));setupWorkflowMask();fitCatalogSelector();revealAssetUse(r);}
function closePanel(restoreFocus=false){if(restoreFocus&&panelAnchor?.isConnected)panelAnchor.focus({preventScroll:true});panel.hidden=true;panel.innerHTML='';panelAnchor?.setAttribute('aria-expanded','false');panelAnchor=null;panelPoint=null;}
function positionPanel(anchor,point){panel.style.left='0';panel.style.top='0';const r=anchor?.getBoundingClientRect(),x=point?.x??r.left,y=point?.y??r.bottom+8;const width=panel.offsetWidth,height=panel.offsetHeight;panel.style.left=Math.max(12,Math.min(innerWidth-width-12,x))+'px';panel.style.top=Math.max(12,panel.classList.contains('reference-popover')?(r.top-height-8>=12?r.top-height-8:Math.min(r.bottom+8,innerHeight-height-12)):y+height>innerHeight-12?(point?.y??r.top)-height-8:y)+'px';}
function popup(anchor,title,html,point){panel.removeAttribute('role');panel.classList.remove('catalog-popup','reference-popover','compact-options','duration-popup','advanced-popup','picture-popup');panelAnchor=anchor;panelPoint=point;panel.innerHTML=`<div class="panel-title"><strong>${title}</strong>${B(I('close'),'close-panel','icon-button','aria-label="关闭菜单"')}</div>${html}`;panel.hidden=false;anchor?.setAttribute('aria-expanded','true');positionPanel(anchor,point);panel.querySelector('[data-param],.context-option,[data-advanced],#negative,[data-mention]')?.focus({preventScroll:true});}
new ResizeObserver(()=>{if(!panel.hidden)positionPanel(panelAnchor,panelPoint);}).observe(panel);
function options(key,items,current){return `<div class="option-list">${items.map(([value,detail])=>`<button data-param="${key}" data-value="${value}" class="${String(current)===String(value)?'chosen':''}" aria-pressed="${String(current)===String(value)}"><span>${value}${detail?`<small>${detail}</small>`:''}</span>${String(current)===String(value)?I('check'):''}</button>`).join('')}</div>`;}
function example(){const d=active().draft;if(liveWorkflow()){d.prompt=liveWorkflow().id==='h3-reference'?'清晨的海岸，海浪缓缓拍打礁石，镜头平稳向前推进，柔和自然光，伴随海浪声。':'将天空和光线改为温暖的金色日落，保留海浪的运动、原有构图与镜头移动。';d.error=null;refreshComposer();scheduleSave();return;}d.prompt=d.type==='video'?'黄昏的摩天轮缓缓转动，镜头沿座舱平稳上升。远处城镇的灯光依次亮起，保持自然的动作与柔和的电影光线。':'一组安静的自然景观，海岸、山谷与森林。清晨柔和的光线，真实的纹理，低饱和色彩，电影摄影感。';d.error=null;refreshComposer();$('#prompt')?.focus();}
