function complete(j){j.status='done';j.ended=j.started+DEMO_DURATION;const count=j.snapshot.type==='video'?1:Number(j.snapshot.count);const jobNumber=Number(j.id.slice(1));j.outputs=Array.from({length:count},(_,i)=>({id:j.id+'o'+i,type:j.snapshot.type,src:j.snapshot.type==='video'?film.src:images[((jobNumber-1)*2+i)%images.length],poster:j.snapshot.type==='video'?film.poster:null}));}
