   if(slot===undefined){toast('首帧和尾帧已满，请先移除要替换的图片。');d.mode=previousMode;return false;}
   const old=d.refs.find(r=>r.slot===slot);d.refs=d.refs.filter(r=>r.slot!==slot);d.refs.push({id:old?.id||nextReferenceId(d,o.type),kind:o.type,name:'生成结果参考',src:o.src,poster:o.poster,slot,sourceOutputId:o.id});
