document.addEventListener('loadedmetadata',e=>{if(e.target.id==='wf-source-video'){const duration=Math.min(3615,Math.floor(e.target.duration*100)/100);if(Number.isFinite(duration)&&duration>=1){active().draft.sourceDuration=duration;const inputs=$$('[data-wf-trim]');inputs.forEach(x=>x.max=duration);const end=$('[data-wf-trim="end"]');if(end&&Number(end.value)>duration)end.value=duration;updateWorkflowTrim();}}},true);document.addEventListener('click',e=>{const choice=e.target.closest('[data-wf-choice]');if(!choice)return;const w=liveWorkflow(),f=w?.fields.find(x=>x.key===choice.dataset.wfChoice);if(!f)return;liveSettings(active().draft,w)[f.key]=typeof f.default==='number'?Number(choice.dataset.value):choice.dataset.value;choice.parentElement.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===choice)));scheduleSave();});function updateDemoTrim(input){const startInput=$('[data-demo-trim="start"]'),endInput=$('[data-demo-trim="end"]');if(!startInput||!endInput)return;const d=active().draft,max=Number(startInput.max),changed=input?.dataset.demoTrim;let start=snapTrim(startInput.value),end=snapTrim(endInput.value);const minimumSpan=.01;if(changed==='start')start=Math.min(start,end-minimumSpan);if(changed==='end')end=Math.max(end,start+minimumSpan);start=snapTrim(Math.max(0,Math.min(start,max-minimumSpan)));end=snapTrim(Math.min(max,Math.max(start+minimumSpan,end)));startInput.value=start;endInput.value=end;d.trimStart=start;d.trimEnd=end;const bar=startInput.closest('.wf-trim');bar.style.setProperty('--trim-start',start/max*100+'%');bar.style.setProperty('--trim-end',end/max*100+'%');$('[data-trim-output="start"]').textContent=trimTime(start);$('[data-trim-output="end"]').textContent=trimTime(end);const video=$('#wf-demo-video');if(video&&input){video.pause();video.currentTime=changed==='start'?start:Math.max(start,end-.01);}scheduleSave();}
