const workspace={assets:[],collections:[],collection:'all',workSelected:new Set(),assetSelected:new Set(),assetFilter:'全部',assetQuery:'',workQuery:'',workTime:'all',removedWorks:false,inspirationQuery:'',inspirationFilter:'全部',picker:false,pickerSlot:undefined,catalogPickerSlot:undefined,catalogPickerKind:undefined,replaceSource:false,imageReferenceOnly:false,prompts:[],reviewSeeded:false};
let storageReady=false,saveTimer,exporting=false,importing=false;
const newId=prefix=>prefix+'-'+crypto.randomUUID();
const kindLabel=kind=>({image:'图像',video:'视频',audio:'音频'}[kind]);
const byteLabel=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.max(1,Math.round(n/1024))+' KB';
function saveRef(r){return {...r,...((r.assetId||r.transient)&&!r.serverAssetId?{src:''}:{})};}
function scheduleSave(){if(!storageReady)return;clearTimeout(saveTimer);saveTimer=setTimeout(saveWorkspace,120);}
async function saveWorkspace(){if(!storageReady)return;const sessions=state.sessions.map(s=>({...s,draft:{...s.draft,error:null,refs:s.draft.refs.map(saveRef)},jobs:s.jobs.map(j=>({...j,snapshot:{...j.snapshot,refs:j.snapshot.refs.map(saveRef)}}))}));try{await writeState({sessions,active:state.active,nextSession,nextJob,collections:workspace.collections,reviewSeeded:workspace.reviewSeeded});}catch{toast('本地保存失败，请检查浏览器存储空间；当前页面中的内容仍保留。');}}
async function initializeWorkspace(){
 if(!production){render();return;}
 try{await openStorage();const [assets,saved]=await Promise.all([readAssets(),readState()]);workspace.assets=assets.sort((a,b)=>b.createdAt-a.createdAt).map(a=>({...a,src:URL.createObjectURL(a.blob)}));if(saved?.sessions?.length){state.sessions=saved.sessions;state.active=saved.active;nextSession=saved.nextSession;nextJob=saved.nextJob;workspace.collections=saved.collections||[];workspace.reviewSeeded=!!saved.reviewSeeded;for(const session of state.sessions){session.liveSubmitting=false;const hydrate=refs=>refs.map(r=>({...r,src:r.serverAssetId?'/api/assets/'+r.serverAssetId+'/file':r.assetId?workspace.assets.find(a=>a.id===r.assetId)?.src||'':r.src,...(r.originalAssetId?{originalSrc:workspace.assets.find(a=>a.id===r.originalAssetId)?.src||r.originalSrc}:{}),...(r.maskAssetId?{maskSrc:workspace.assets.find(a=>a.id===r.maskAssetId)?.src||''}:{})})).filter(r=>r.src);session.draft.refs=hydrate(session.draft.refs);renumberDraftReferences(session.draft,{slotOrder:workflow(session)?.interface?.media?.map(m=>m.id)||[]});if(!session.scope.startsWith('wf:'))normalizeDraft(session.draft);for(const j of session.jobs){j.rerunning=false;j.snapshot.refs=hydrate(j.snapshot.refs);if(j.real&&j.status==='running'&&!j.remoteId&&j.stage?.startsWith('正在上传')){j.status='failed';j.error='素材上传被刷新中断，请重新提交。';j.ended=Date.now();}if(j.status==='running'&&!j.real){j.status='failed';j.reason='interrupted';j.ended=Date.now();}}}}storageReady=true;}
 catch{toast('此浏览器无法保存本地素材。生成布局仍可体验，请使用允许本地存储的浏览器重试。');}
 if(new URLSearchParams(location.search).has('demo')&&!workspace.reviewSeeded){seedReview();workspace.reviewSeeded=true;}
 render();scheduleSave();
}
document.addEventListener('click',scheduleSave);document.addEventListener('input',scheduleSave);document.addEventListener('change',scheduleSave);window.addEventListener('pagehide',()=>saveWorkspace());

