function discoveries(){const recent=(workflows.filter(w=>w.live).length?workflows.filter(w=>w.live):workflows).slice(0,4);return `<div class="discovery"><section><div class="section-heading"><h2>最近上新</h2><a class="text-control control" href="#workflows">查看全部 ${I('arrow')}</a></div><div class="new-flow-grid">${recent.map(w=>workflowCard(w,false)).join('')}</div></section><section><div class="section-heading"><h2>精选作品</h2><span class="quiet-label">演示选集</span></div><div class="featured-grid">${featured.map((f,i)=>`<button class="featured-card" data-action="featured" data-index="${i}"><img src="assets/${f.cover}" alt="${f.title}" loading="lazy"><span class="featured-caption"><strong>${f.title}</strong><small>${f.tag}</small></span><span class="featured-arrow">${I('arrow')}</span></button>`).join('')}</div></section></div>`;}
