function referenceLimit(d=active().draft){const w=liveWorkflow();if(w)return w.maxImages+w.maxVideos;return workflow(active())?.interface?.media?.length|| (workflow(active())?Infinity:d.mode==='首尾帧'?2:getModel(d).refLimit);}
function allowedKinds(d=active().draft){const w=workflow(active());if(workspace?.catalogPickerKind)return[workspace.catalogPickerKind];if(workspace?.replaceSource)return['video'];if(w?.live)return w.maxVideos?['image','video']:['image'];if(videoEditWorkflows.has(w?.id))return videoSourceOnlyWorkflows.has(w.id)?['video']:['image','video'];if(d.type==='image'||d.mode==='首尾帧'||w?.mode==='image')return['image'];if(w?.mode==='video')return['video'];return w?['image','video','audio']:getModel(d).kinds;}
function referenceProblem(d,session=active()){if(liveWorkflow(session))return liveProblem(d,liveWorkflow(session));const w=workflow(session),refs=visibleRefs(d,w),limit=w?(w.interface?.media?.length||Infinity):d.mode==='首尾帧'?2:getModel(d).refLimit;let kinds;if(videoEditWorkflows.has(w?.id))kinds=videoSourceOnlyWorkflows.has(w.id)?['video']:['image','video'];else kinds=w?.mode==='video'?['video']:w?.mode==='image'||d.type==='image'||d.mode==='首尾帧'?['image']:w?['image','video','audio']:getModel(d).kinds;if(refs.some(r=>!kinds.includes(r.kind)))return `当前${w?'工作流':getModel(d).name}仅支持${kinds.map(kindLabel).join('、')}参考。请移除不兼容的素材或切换模型。`;if(refs.length>limit)return `当前最多支持 ${limit} 份参考，请移除多余素材。`;if(!w&&d.model==='seedance-2.0'){for(const[kind,n]of[['image',9],['video',3],['audio',3]])if(refs.filter(r=>r.kind===kind).length>n)return `Seedance 2.0 最多使用 ${n} 份${kindLabel(kind)}参考，请移除多余素材。`;}return '';}
