document.addEventListener('wheel',e=>{
 const list=e.target.closest?.('.catalog-picker-works-list');if(!list||e.ctrlKey||list.scrollWidth<=list.clientWidth)return;
 const unit=e.deltaMode===1?20:e.deltaMode===2?list.clientWidth:1;
 const delta=(Math.abs(e.deltaX)>Math.abs(e.deltaY)?e.deltaX:e.deltaY)*unit;
 if(!delta)return;
 const before=list.scrollLeft;list.scrollLeft=Math.max(0,Math.min(list.scrollWidth-list.clientWidth,before+delta));
 if(list.scrollLeft!==before)e.preventDefault();
},{passive:false});

