function refreshAssets(){const box=$('#asset-panel');if(box){const top=box.querySelector('.asset-library-content')?.scrollTop||0,focused=document.activeElement?.id==='asset-search',pos=$('#asset-search')?.selectionStart;box.innerHTML=assetPanel(workspace.picker);if(box.querySelector('.asset-library-content'))box.querySelector('.asset-library-content').scrollTop=top;if(focused){$('#asset-search').focus();$('#asset-search').setSelectionRange(pos,pos);}}}
async function importAssets(files){if(importing){toast('正在导入上一批素材，请稍候。');return[];}if(!storageReady){toast('本地素材存储不可用，请检查浏览器设置。');return[];}importing=true;const added=[],errors=[];let duplicates=0;try{for(const file of files){const kind=file.type.split('/')[0];if(!['image','video','audio'].includes(kind)){errors.push(file.name+'：请选择图像、视频或音频');continue;}const limit={image:40,video:200,audio:50}[kind];if(file.size>limit*1048576){errors.push(file.name+'：超过 '+limit+' MB，请压缩后再导入');continue;}const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))].map(n=>n.toString(16).padStart(2,'0')).join('');const old=workspace.assets.find(a=>a.hash===hash);if(old){added.push(old);duplicates++;continue;}const a={id:newId('asset'),kind,name:file.name,size:file.size,hash,createdAt:Date.now(),blob:file};try{await putAsset(a);a.src=URL.createObjectURL(file);workspace.assets.unshift(a);added.push(a);}catch{errors.push(file.name+'：保存失败，请释放浏览器存储空间后重试');}}
 }finally{importing=false;}
 for(const a of added)if(!workspace.picker||allowedKinds().includes(a.kind)){if(workspace.pickerSlot!==undefined||workspace.catalogPickerSlot!==undefined)workspace.assetSelected.clear();workspace.assetSelected.add(a.id);}
 refreshAssets();if(route().name==='assets'&&!dialog.open)render();
 if(errors.length){let e=$('#import-error');if(!e){$('#asset-panel')?.insertAdjacentHTML('afterbegin','<div id="import-error" class="inline-error" role="alert"></div>');e=$('#import-error');}if(e)e.textContent=errors.slice(0,5).join('；');else toast(errors[0]);}
 if(added.length)toast(`已导入 ${added.length-duplicates} 份素材${duplicates?'，复用 '+duplicates+' 份重复素材':''}。`);return added;
}
function attachAsset(a,d=active().draft,slot){const prior=slot===undefined?null:d.refs.find(r=>r.slot===slot);if(prior&&sameMedia(prior,a))return;if(prior)d.refs=d.refs.filter(r=>r!==prior);if(d.refs.some(r=>r.slot===slot&&sameMedia(r,a)))return;const kind=a.kind;d.refs.push({id:prior?.kind===kind?prior.id:nextReferenceId(d,kind),assetId:a.id,kind,name:a.name,src:a.src,...(slot!==undefined?{slot}:{}),local:true});renumberDraftReferences(d,{removedIds:prior&&prior.kind!==kind?[prior.id]:[]});}
function bindCatalogAsset(a,slotId,session=active()){const w=workflow(session),slot=w?.interface?.media?.find(s=>s.id===slotId);if(!slot||slot.kind!==a.kind){toast('素材类型与参考位不匹配。');return false;}const d=session.draft,old=d.refs.find(r=>r.catalogSlot===slot.id);d.refs=d.refs.filter(r=>r.catalogSlot!==slot.id);d.refs.push({id:old?.kind===a.kind?old.id:nextReferenceId(d,a.kind),assetId:a.id,kind:a.kind,name:a.name,src:a.src,catalogSlot:slot.id});renumberDraftReferences(d,{removedIds:old&&old.kind!==a.kind?[old.id]:[],slotOrder:w.interface.media.map(m=>m.id)});d.error=null;if(active()===session)refreshComposer();scheduleSave();return true;}
async function transientAsset(file){
 const kind=file?.type.split('/')[0],limit={image:40,video:200,audio:50}[kind];
 if(!file||!limit||file.size>limit*1048576){toast('文件类型不支持或超出大小限制。');return null;}
 const a={id:newId('temporary'),kind,name:file.name,size:file.size,createdAt:Date.now(),blob:file,hidden:true};
 try{await putAsset(a);}catch{toast('本次素材保存失败，请检查浏览器存储空间。');return null;}
 a.src=URL.createObjectURL(file);workspace.assets.unshift(a);return a;
}
function attachSelected(create=false){const chosen=workspace.assets.filter(a=>workspace.assetSelected.has(a.id));if(!chosen.length)return;if(workspace.catalogPickerSlot!==undefined){if(chosen.length!==1||chosen[0].kind!==workspace.catalogPickerKind){toast('这个参考位只能选择一份对应类型的素材。');return;}if(!bindCatalogAsset(chosen[0],workspace.catalogPickerSlot))return;workspace.catalogPickerSlot=undefined;workspace.catalogPickerKind=undefined;workspace.picker=false;workspace.imageReferenceOnly=false;dialog.close();toast('参考素材已绑定。');return;}if(create){const type=chosen.some(a=>a.kind!=='image')?'video':'image';makeSession('model',type);}const d=active().draft,old=[...d.refs];if(workspace.imageReferenceOnly&&chosen.some(a=>a.kind!=='image')){toast('这里只能选择图片。');return;}if(workspace.replaceSource){if(chosen.length!==1||chosen[0].kind!=='video'){toast('更换原视频时请选择一段视频。');return;}d.refs=d.refs.filter(r=>r.kind!=='video');d.sourceDuration=undefined;d.trimStart=0;d.trimEnd=undefined;if(liveWorkflow())liveSettings(d,liveWorkflow()).trim_start=0;}if(d.mode==='纯文本')d.mode='全能参考';if(workspace.pickerSlot!==undefined&&chosen.length!==1){toast('首帧或尾帧一次选择一张图片。');return;}chosen.forEach(a=>attachAsset(a,d,workspace.pickerSlot));normalizeDraft(d);const problem=referenceProblem(d);if(problem){d.refs=old;toast(problem);return;}d.error=null;workspace.picker=false;workspace.pickerSlot=undefined;workspace.replaceSource=false;workspace.imageReferenceOnly=false;dialog.close();location.hash='session/'+active().id;render();$('#prompt')?.focus();scheduleSave();toast(`已添加 ${chosen.length} 份参考，可在描述中输入 @ 引用。`);}
async function addFiles(files,slot){const added=await importAssets(files),d=active().draft,old=[...d.refs];if(d.mode==='纯文本')d.mode='全能参考';added.forEach(a=>attachAsset(a,d,slot===undefined?undefined:Number(slot)));normalizeDraft(d);const problem=referenceProblem(d);if(problem){d.refs=old;inlineError(problem+' 素材已保存在素材库。','refs-library');}else{d.error=null;refreshComposer();}scheduleSave();}

function filteredWorks(){return allOutputs().filter(row=>!row.o.removedAt&&(state.filter==='全部'||row.o.type===(state.filter==='图像'?'image':'video'))&&matchesWork(row,workspace.workQuery,workspace.workTime,Date.now(),workflows));}
function collectionName(id){return workspace.collections.find(c=>c.id===id)?.name||'未分类';}
function workTitle(j,o){return (j.snapshot.prompt|| (o.type==='video'?'视频创作':'图像创作')).split(/[。！？\n]/)[0].slice(0,22);}
function workSignature(){return JSON.stringify(filteredWorks().map(({o,j})=>[o.id,o.src,o.poster,o.type,o.collectionId,o.removedAt,j.snapshot.prompt]));}

function worksEmpty(){const total=allOutputs().length;return `<div class="useful-empty"><h2>${total?'没有匹配的作品':'从第一段描述开始'}</h2><p>${total?'换个关键词，或清除类型和时间筛选。':'完成后的结果会自动保存在这里。'}</p>${total?B('清除筛选','all-works','button'):'<a href="#workflows" class="button primary">开始创作 '+I('arrow')+'</a>'}</div>`;}
function workItemMarkup(o,j,i){return `${outputHTML(o,j,i)}<div class="work-caption"><strong>${esc(workTitle(j,o))}</strong><p>${esc((j.snapshot.prompt||'').slice(0,78)||'使用参考素材创作')}${j.snapshot.prompt?.length>78?'…':''}</p></div>`;}
function refreshLibrary(){
 if(route().name!=='library'||dialog.open)return;
 const signature=workSignature();if(signature===librarySignature)return;librarySignature=signature;
 const content=$('#works-content'),rows=filteredWorks();if(!content)return;
 let grid=content.querySelector('.works-grid');if(!rows.length){content.innerHTML=worksEmpty();return;}
 if(!grid){content.innerHTML='<div class="works-grid"></div>';grid=content.firstElementChild;}
 const existing=new Map([...grid.children].map(el=>[el.querySelector('[data-output]')?.dataset.output,el]));let cursor=grid.firstElementChild;
 for(const [i,{o,j}] of rows.entries()){
  let el=existing.get(o.id);if(!el){el=document.createElement('div');el.className='work-item';el.innerHTML=workItemMarkup(o,j,i);}else{existing.delete(o.id);const media=el.querySelector('[data-view] img,[data-view] video');if(media&&media.getAttribute('src')!==o.src)media.setAttribute('src',o.src);el.querySelector('.work-caption strong').textContent=workTitle(j,o);el.querySelector('.work-caption p').textContent=(j.snapshot.prompt||'使用参考素材创作').slice(0,78)+(j.snapshot.prompt?.length>78?'…':'');}
  if(el!==cursor)grid.insertBefore(el,cursor);else cursor=cursor.nextElementSibling;
 }
 for(const el of existing.values())el.remove();syncWorkSelection();
}
function library(){librarySignature=workSignature();const all=filteredWorks();return `<section class="library-page works-page"><header class="library-head compact-head"><h1>我的作品</h1><div class="category-tabs" aria-label="作品类型">${['全部','图像','视频'].map(t=>`<button class="category ${state.filter===t?'active':''}" data-library-filter="${t}" aria-pressed="${state.filter===t}">${t}</button>`).join('')}</div><div class="head-actions works-search-tools">${B(I('trash')+'已移除','restored-works','small-button')}<label class="searchbox">${I('search')}<input id="works-search" aria-label="搜索我的作品" placeholder="搜索作品、描述或工具" value="${esc(workspace.workQuery)}"></label>${selectControl({id:'works-time',label:'作品时间',value:workspace.workTime,options:[{value:'all',label:'全部时间'},{value:'7',label:'最近 7 天'},{value:'30',label:'最近 30 天'}]})}</div></header><div id="works-content">${all.length?`<div class="works-grid">${all.map(({o,j},i)=>`<div class="work-item">${workItemMarkup(o,j,i)}</div>`).join('')}</div>`:worksEmpty()}</div></section><div id="work-batch-bar" class="work-batch-bar glass" ${workspace.workSelected.size?'':'hidden'}>${workBatchMarkup()}</div>`;}
function workBatchMarkup(){const n=workspace.workSelected.size;return `<strong>已选 ${n} 项</strong>${B('全选当前','select-works','small-button')}${B('批量导出 ZIP','export-works','small-button primary',exporting?'disabled':'')}${B('并排对比','compare-works','small-button',n<2||n>4?'disabled':'')}${B('批量移除','remove-works','small-button danger-action')}${B('清空选择','clear-works','small-button')}`;}
function syncWorkSelection(){const ids=allOutputs().filter(({o})=>!o.removedAt).map(({o})=>o.id);for(const id of workspace.workSelected)if(!ids.includes(id))workspace.workSelected.delete(id);$$('[data-output]').forEach(el=>{const on=workspace.workSelected.has(el.dataset.output);el.classList.toggle('selected',on);const button=el.querySelector('[data-select]');button.classList.toggle('active',on);button.innerHTML=I(on?'check':'plus')+'<span>选择</span>';button.setAttribute('aria-label',(on?'取消选择':'选择')+'作品');button.setAttribute('aria-pressed',on);});const bar=$('#work-batch-bar');if(bar){bar.hidden=!workspace.workSelected.size;bar.innerHTML=workBatchMarkup();}}
function toggleWork(id){workspace.workSelected.has(id)?workspace.workSelected.delete(id):workspace.workSelected.add(id);syncWorkSelection();}
function collectionForm(id){const c=workspace.collections.find(c=>c.id===id);modal(c?'重命名分类':'新建分类',`<form id="collection-form" data-id="${c?.id||''}"><label for="collection-name">分类名称</label><input id="collection-name" class="solid-input" maxlength="30" value="${esc(c?.name||'')}" placeholder="例如：品牌短片、产品海报" required><p id="collection-error" class="form-error" role="alert"></p><div class="dialog-actions">${B('取消','close-dialog','small-button')}<button type="submit" class="button primary">${c?'保存名称':'创建分类'}</button></div></form>`,'small-dialog');$('#collection-name').focus();}
function manageCollections(){modal('管理分类',`${workspace.collections.length?`<div class="collection-list">${workspace.collections.map(c=>`<div><span>${I('folder')}${esc(c.name)}</span>${B('重命名','rename-collection','small-button',`data-id="${c.id}"`)}${B('移除分类','delete-collection','small-button',`data-id="${c.id}"`)}</div>`).join('')}</div><p class="panel-note">移除分类后，里面的作品会保留在「未分类」。</p>`:'<p class="panel-note">按项目或用途建立分类，让作品更容易找到。</p>'}${B('新建分类','new-collection','button primary')}`,'small-dialog');}
function moveWorks(){modal('移入分类',`<div class="option-list"><button data-move-collection="">未分类</button>${workspace.collections.map(c=>`<button data-move-collection="${c.id}">${I('folder')}${esc(c.name)}</button>`).join('')}</div>${B('新建分类','new-collection','small-button')}`,'small-dialog');}
async function exportWorks(){if(exporting)return;const selected=allOutputs().filter(({o})=>workspace.workSelected.has(o.id));if(!selected.length)return;exporting=true;syncWorkSelection();toast('正在打包 '+selected.length+' 件作品…');try{const files=[],manifest=[];for(const [{o,j},i] of selected.map((x,i)=>[x,i])){const response=await fetch(o.src);if(!response.ok)throw new Error('无法读取作品文件，请稍后重试。');const type=o.type==='video'?'mp4':o.src.endsWith('.png')?'png':'jpg',name=`${String(i+1).padStart(2,'0')}-${o.id}.${type}`;files.push({name,data:new Uint8Array(await response.arrayBuffer())});manifest.push({file:name,prompt:j.snapshot.prompt,model:j.snapshot.workflowId?null:getModel(j.snapshot).name,workflow:j.snapshot.workflowId?(workflows.find(w=>w.id===j.snapshot.workflowId)?.name||j.snapshot.workflowId):null,parameters:j.snapshot,collection:collectionName(o.collectionId),demo:!j.real});}files.push({name:'作品说明.json',data:JSON.stringify(manifest.map(({parameters,...rest})=>({...rest,parameters:{ratio:parameters.ratio,quality:parameters.quality,duration:parameters.duration,count:parameters.count,negative:parameters.negative||'',workflowId:parameters.workflowId||null,advanced:parameters.advanced||{},workflowParameters:parameters.liveSettings||null}})),null,2)});downloadBlob(createZip(files),'映序-作品集-'+new Date().toISOString().slice(0,10)+'.zip');toast('已导出 '+selected.length+' 件作品和提示词说明。');}catch(e){toast('导出失败：'+e.message+' 已保留选择，可重试。');}finally{exporting=false;syncWorkSelection();}}

function promptRows(text){return text.replace(/^\uFEFF/,'').split(/\r?\n/).map(t=>t.trim()).filter(Boolean);}
function batchPrompts(){workspace.prompts=[];modal('批量导入提示词',`<p class="dialog-description">每行一条提示词。先预览和修改，再按当前模型与参数逐条创建任务。</p><label class="file-import control small-button">${I('plus')}选择 TXT / CSV / JSON<input type="file" data-prompt-files multiple accept=".txt,.csv,.json" aria-label="导入提示词文件"></label><textarea id="batch-prompt-input" class="solid-input" rows="6" placeholder="海边的玻璃建筑，柔和晨光\n山谷中的云海，广角远景"></textarea><p id="batch-error" class="form-error" role="alert"></p><div id="batch-preview"></div><div class="dialog-actions">${B('预览任务','preview-prompts','small-button')}${B('创建任务','run-prompts','button primary','disabled')}</div>`,'batch-dialog');}
function parsePromptFile(text,name){if(name.toLowerCase().endsWith('.json')){const obj=JSON.parse(text),list=Array.isArray(obj)?obj:obj.prompts;if(!Array.isArray(list))throw new Error('JSON 请使用字符串数组或 {"prompts": [...]}。');return list.map(v=>typeof v==='string'?v:typeof v?.prompt==='string'?v.prompt:'').filter(Boolean);}if(name.toLowerCase().endsWith('.csv')){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV 引号未闭合，请检查文件。');row.push(cell);if(row.some(Boolean))rows.push(row);if(!rows.length)return[];const header=rows[0].map(v=>v.replace(/^\uFEFF/,'').trim().toLowerCase()),col=header.findIndex(v=>['prompt','提示词','描述'].includes(v));return(col>=0?rows.slice(1):rows).map(r=>r[col>=0?col:0]?.trim()).filter(Boolean);}return promptRows(text);}
function previewPrompts(){const limit=workflow(active())?6000:12000,prompts=promptRows($('#batch-prompt-input').value);workspace.prompts=[];if(!prompts.length||prompts.length>50||prompts.some(p=>p.length>limit)){ $('#batch-error').textContent=!prompts.length?'先粘贴或导入提示词。':prompts.length>50?'一次最多导入 50 条，请拆分后重试。':`单条描述最多 ${limit} 个字符，请缩短后重试。`;$('[data-action="run-prompts"]').disabled=true;return;}workspace.prompts=prompts;$('#batch-error').textContent='';$('#batch-preview').innerHTML=`<div class="batch-summary"><strong>${prompts.length} 个任务</strong><span>${liveWorkflow()?liveWorkflow().name+' · 使用当前算力卡':getModel(active().draft).name+' · 演示任务'}</span></div><ol>${prompts.map(p=>`<li>${esc(p)}</li>`).join('')}</ol>`;const b=$('[data-action="run-prompts"]');b.disabled=false;b.textContent=`生成 ${prompts.length} 个任务 · ${liveWorkflow()?'算力卡计费':'演示'}`;}
async function runPrompts(){const list=[...workspace.prompts];if(!list.length)return;const d=active().draft,problem=referenceProblem(d);if(problem){$('#batch-error').textContent=problem;return;}if(d.mode==='首尾帧'&&(!d.refs.some(r=>r.slot===0)||!d.refs.some(r=>r.slot===1))){$('#batch-error').textContent='请先在创作区补齐首帧和尾帧。';return;}const ids=visibleRefs(d).map(r=>'@'+r.id),missing=list.flatMap(p=>(p.match(/@(图片|视频|音频)\d+/g)||[]).filter(t=>!ids.includes(t)));if(missing.length){$('#batch-error').textContent=[...new Set(missing)].join('、')+' 没有对应素材，请修改后重新预览。';return;}dialog.close();const session=active();for(const prompt of list){const ok=await submit({...d,prompt,refs:[...d.refs]},session);if(ok===false)break;}workspace.prompts=[];scheduleSave();toast('已提交批量任务，每条提示词独立一栏。');}

function handleWorkspaceAction(a,el){switch(a){case'remove-work':removeWorks([el.dataset.id]);break;case'remove-works':removeWorks([...workspace.workSelected]);break;case'restored-works':showRemovedWorks();break;case'restore-work':restoreWorks([el.dataset.id]);break;case'restore-all-works':restoreWorks(allOutputs().filter(({o})=>o.removedAt).map(({o})=>o.id));break;case'save-output':saveOutputAsset(el.dataset.id,el);break;case'open-assets':workspace.replaceSource=false;openAssetPicker(el.dataset.slot);break;case'open-image-assets':workspace.replaceSource=false;openAssetPicker(undefined,true);break;case'attach-assets':attachSelected();break;case'assets-create':workspace.pickerSlot=undefined;attachSelected(true);break;case'select-assets':{const list=assetList(workspace.picker).filter(a=>!workspace.picker||allowedKinds().includes(a.kind));if(workspace.pickerSlot!==undefined){toast('首帧或尾帧一次选择一张图片。');break;}const all=list.every(a=>workspace.assetSelected.has(a.id));list.forEach(a=>all?workspace.assetSelected.delete(a.id):workspace.assetSelected.add(a.id));refreshAssets();break;}case'clear-assets':workspace.assetSelected.clear();refreshAssets();break;case'reset-assets':workspace.assetQuery='';workspace.assetFilter='全部';refreshAssets();break;case'asset-uses':showAssetUses();break;case'remove-asset-draft':{const session=state.sessions.find(s=>s.id===el.dataset.session);if(!session)break;session.draft.refs=session.draft.refs.filter(r=>r.id!==el.dataset.ref);renumberDraftReferences(session.draft,{removedIds:[el.dataset.ref],slotOrder:workflow(session)?.interface?.media?.map(m=>m.id)||[]});session.draft.error=null;scheduleSave();showAssetUses();toast('已移除该草稿的参考素材，原文件与历史任务仍保留。');break;}case'delete-assets':{const selected=workspace.assets.filter(a=>workspace.assetSelected.has(a.id));if(selected.some(a=>assetReferences(a,state.sessions).length)){showAssetUses(true);break;}(async()=>{try{for(const a of selected){await deleteAsset(a.id);URL.revokeObjectURL(a.src);workspace.assets=workspace.assets.filter(x=>x.id!==a.id);}workspace.assetSelected.clear();render();toast('已移除 '+selected.length+' 份未使用素材。');}catch{toast('移除失败，请重试。');}})();break;}case'featured':{const f=featured[Number(el.dataset.index)];modal(f.title,`<img class="featured-preview" src="assets/${f.cover}" alt="${esc(f.title)}"><p class="featured-prompt">${esc(f.prompt)}</p><p class="inspiration-note">示例配方 · API 图像生成 · 16:9 · 2K · 无原始素材记录</p><div class="dialog-actions">${B('用同样方式制作','use-featured','button primary',`data-index="${el.dataset.index}"`)}${B(I('assets')+'保存到素材库','save-featured','small-button',`data-index="${el.dataset.index}"`)}</div>`,'featured-dialog');break;}case'use-featured':useFeatured(Number(el.dataset.index));break;case'save-featured':{const f=featured[Number(el.dataset.index)];(async()=>{const response=await fetch('assets/'+f.cover);const blob=await response.blob();await importAssets([new File([blob],f.title+'.'+f.cover.split('.').at(-1),{type:blob.type})]);})();break;}case'new-collection':collectionForm();break;case'rename-collection':collectionForm(el.dataset.id);break;case'manage-collections':manageCollections();break;case'delete-collection':{const id=el.dataset.id;workspace.collections=workspace.collections.filter(c=>c.id!==id);allOutputs().forEach(({o})=>{if(o.collectionId===id)delete o.collectionId;});if(workspace.collection===id)workspace.collection='all';render();manageCollections();scheduleSave();toast('分类已移除，作品保留在未分类中。');break;}case'all-works':workspace.collection='all';state.filter='全部';workspace.workQuery='';workspace.workTime='all';render();break;case'select-works':{const list=filteredWorks(),all=list.every(({o})=>workspace.workSelected.has(o.id));list.forEach(({o})=>all?workspace.workSelected.delete(o.id):workspace.workSelected.add(o.id));syncWorkSelection();break;}case'clear-works':workspace.workSelected.clear();syncWorkSelection();break;case'move-works':moveWorks();break;case'export-works':exportWorks();break;case'compare-works':{const selected=[...workspace.workSelected],types=new Set(selected.map(id=>findOutput(id)?.o.type));if(types.size!==1){toast('请选同一类型的 2–4 个作品进行对比。');break;}state.selected=new Set(selected);compare('works');break;}case'batch-prompts':batchPrompts();break;case'preview-prompts':previewPrompts();break;case'run-prompts':runPrompts();break;default:return false;}return true;}
document.addEventListener('click',e=>{const asset=e.target.closest('[data-asset]');if(asset){if(asset.getAttribute('aria-disabled')==='true')return;const id=asset.dataset.asset;if(workspace.assetSelected.has(id))workspace.assetSelected.delete(id);else{if(workspace.pickerSlot!==undefined||workspace.catalogPickerSlot!==undefined)workspace.assetSelected.clear();workspace.assetSelected.add(id);}refreshAssets();}const filter=e.target.closest('[data-asset-filter]');if(filter){workspace.assetFilter=filter.dataset.assetFilter;refreshAssets();}const coll=e.target.closest('[data-collection]');if(coll){workspace.collection=coll.dataset.collection;render();}const move=e.target.closest('[data-move-collection]');if(move){allOutputs().filter(({o})=>workspace.workSelected.has(o.id)).forEach(({o})=>{o.collectionId=move.dataset.moveCollection||null;});dialog.close();workspace.workSelected.clear();render();scheduleSave();toast('分类已更新。');}const duration=e.target.closest('[data-duration-index]');if(duration)setDuration(Number(duration.dataset.durationIndex));});
document.addEventListener('input',e=>{if(e.target.id==='duration-range')setDuration(Number(e.target.value));if(e.target.matches('[data-wf-trim]'))updateWorkflowTrim(e.target);if(e.target.matches('[data-wf-field]')){const w=liveWorkflow(),f=w?.fields.find(x=>x.key===e.target.dataset.wfField);if(f){const v=typeof f.default==='number'?Number(e.target.value):e.target.value;liveSettings(active().draft,w)[f.key]=v;const out=document.querySelector(`[data-wf-output="${f.key}"]`);if(out)out.textContent=v+(f.key==='duration'?' 秒':f.key==='steps'?' 步':'');scheduleSave();}}if(e.target.id==='wf-brush-size')$('#wf-brush-value').textContent=e.target.value+' px';if(e.target.id==='asset-search'){workspace.assetQuery=e.target.value;refreshAssets();}if(e.target.id==='batch-prompt-input'){workspace.prompts=[];$('#batch-preview').innerHTML='';$('[data-action="run-prompts"]').disabled=true;$('[data-action="run-prompts"]').textContent='创建任务';}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-vault-files]')){const slot=workspace.catalogPickerSlot,kind=workspace.catalogPickerKind,session=active(),editing=slot!==undefined&&workflow(session)?.category==='图像编辑',added=editing?[await transientAsset(e.target.files[0])].filter(Boolean):await importAssets([...e.target.files]);if(slot!==undefined&&added.length===1&&added[0].kind===kind&&active()===session&&bindCatalogAsset(added[0],slot,session)){workspace.catalogPickerSlot=undefined;workspace.catalogPickerKind=undefined;workspace.picker=false;workspace.imageReferenceOnly=false;dialog.close();toast(editing?'参考图已绑定，仅用于本次创作。':'参考素材已绑定。');}}if(e.target.matches('[data-prompt-files]')){workspace.prompts=[];$('#batch-preview').innerHTML='';$('[data-action="run-prompts"]').disabled=true;try{const rows=[];for(const file of e.target.files){if(file.size>1048576)throw new Error(file.name+' 超过 1 MB，请拆分文件。');rows.push(...parsePromptFile(await file.text(),file.name));}$('#batch-prompt-input').value=rows.map(t=>t.replace(/\r?\n/g,' ')).join('\n');previewPrompts();}catch(err){$('#batch-error').textContent=err instanceof SyntaxError?'JSON 格式有误，请使用字符串数组，例如：["海边晨光", "森林小径"]，修改后重新导入。':err.message;}}});
document.addEventListener('submit',e=>{if(e.target.id!=='collection-form')return;e.preventDefault();const name=$('#collection-name').value.trim(),id=e.target.dataset.id;if(!name){$('#collection-error').textContent='请输入分类名称。';return;}if(workspace.collections.some(c=>c.name===name&&c.id!==id)){ $('#collection-error').textContent='已有同名分类，请换一个名称。';return;}if(id)workspace.collections.find(c=>c.id===id).name=name;else workspace.collections.push({id:newId('collection'),name});dialog.close();render();scheduleSave();toast(id?'分类名称已保存。':'分类已创建，可选择作品批量移入。');});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-asset-drop]')){e.preventDefault();e.target.closest('[data-asset-drop]').classList.add('dragover');}});
document.addEventListener('dragleave',e=>e.target.closest('[data-asset-drop]')?.classList.remove('dragover'));
document.addEventListener('drop',e=>{if(workspace.picker)return;if(e.target.closest('[data-asset-drop]')){e.preventDefault();e.target.closest('[data-asset-drop]').classList.remove('dragover');importAssets([...e.dataTransfer.files]);}});

// Review URLs load explicitly labelled local examples; no model is called.
function seedReview(){const mode=new URLSearchParams(location.search).get('demo');if(!production||!['results','progress','error'].includes(mode))return;resolveSession();const s=active();s.draft.prompt='一组安静的自然景观，柔和晨光、真实材质、低饱和色彩。';s.draft.count=4;for(let n=0;n<(mode==='results'?2:1);n++){const snap={...s.draft,refs:[]};if(n){snap.prompt='让画面更开阔，突出自然纹理与空间层次，保持柔和的电影光线。';snap.count=2;}const j={id:'j'+nextJob++,snapshot:snap,cost:cost(snap),started:Date.now()-(mode==='progress'?4500:DEMO_DURATION),outputs:[],status:'running',ended:null};s.jobs.push(j);if(mode==='results')complete(j);if(mode==='error'){j.status='failed';j.ended=Date.now();}}s.title=s.jobs[0].snapshot.prompt.slice(0,28);s.draft.prompt='';}
function viewportHeight(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||innerHeight)+'px');}viewportHeight();window.visualViewport?.addEventListener('resize',viewportHeight);
await initializeWorkspace();if(production)setInterval(tickJobs,350);

function advancedMarkup(d,w){return `${!w?`<details class="mobile-model-disclosure"><summary>模型 · ${getModel(d).name}</summary>${modelOptions(d)}</details>`:''}${advancedFields(d,w)}<section class="advanced-negative"><label class="intent-label" for="negative">反向提示词 <span>可选</span></label><textarea id="negative" class="negative-input" placeholder="写下要避免的元素，如：水印、背景杂物" maxlength="2000" rows="3">${esc(d.negative||'')}</textarea></section><div class="advanced-footer">${B('恢复默认','reset-advanced','text-control')}${B('完成','close-panel','button primary')}</div>`;}
function updateAdvancedBadge(){const b=$('.settings-count');if(!b)return;const n=advancedCount(active().draft,workflow(active()));b.hidden=!n;b.textContent=n;}
function setAdvanced(key,value){const d=active().draft;d.advanced={...(d.advanced||{}),[key]:value};d.advanced=advancedValues(d,workflow(active()));const range=$(`[data-advanced="${key}"]`);if(range){range.style.setProperty('--range-progress',d.advanced[key]+'%');range.setAttribute('aria-valuetext',d.advanced[key]+'%');$(`#value-${key}`).innerHTML=d.advanced[key]+'<small>%</small>';}document.querySelectorAll(`[data-advanced-choice="${key}"]`).forEach(b=>{const on=b.dataset.value===d.advanced[key];b.classList.toggle('chosen',on);b.setAttribute('aria-pressed',on);});const values=d.advanced,intensity=values.edit??values.scene??values.identity??values.style??45;const effect=document.querySelector('.effect-layer');effect?.style.setProperty('--edit-intensity',intensity/100);effect?.style.setProperty('--preserve',((values.background??values.subject??0)*.7)+'%');const label=document.querySelector('[data-effect-label]');if(label)label.textContent=Object.entries(values).map(([k,v])=>({edit:'修改',scene:'背景贴合',identity:'角色贴合',style:'风格',background:'背景保留',subject:'人物保留',blend:'边缘融合',motion:'动作保留',consistency:'一致性'}[k]||k)+' '+v+(typeof v==='number'?'%':'')).join(' · ');updateAdvancedBadge();scheduleSave();}
function showJobSettings(id){const found=findJob(id);if(!found)return;const d=found.j.snapshot,w=workflows.find(w=>w.id===d.workflowId)||workflow(found.s);if(d.catalogLive||found.j.real&&w?.catalogOnly){const values={...catalogValuesFromSettings(w,d.liveSettings||{}),...(d.catalogValues||{})},rows=(w?.interface?.controls||[]).filter(f=>Object.hasOwn(values,f.id));modal('本次生成参数',`<p class="settings-context">${esc(w?.name||'工作流')} · 算力卡真实生成</p><dl class="parameter-summary">${rows.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(values[f.id])}</dd></div>`).join('')}</dl>${w?.interface?.texts.some(t=>t.role==='prompt')?`<div class="saved-negative"><span>创作描述</span><p>${esc(d.prompt||'未填写')}</p></div>`:''}<p class="live-task-id">任务：${esc(found.j.promptId||'尚未提交')}</p><div class="dialog-actions"><a class="small-button" href="/api/jobs/${found.j.remoteId}/workflow" download>下载执行图 JSON</a>${B('用这些参数重新编辑','reedit','button primary',`data-job="${id}"`)}</div>`,'small-dialog');return;}if(found.j.real)return liveJobSettings(id);if(d.catalogDemo){const rows=(w?.interface?.controls||[]).filter(f=>Object.hasOwn(d.catalogValues||{},f.id));modal('本次演示参数',`<p class="settings-context">${esc(w?.name||'工作流')} · 未调用模型</p><dl class="parameter-summary">${rows.length?rows.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(d.catalogValues[f.id])}</dd></div>`).join(''):'<div><dt>节点参数</dt><dd>使用目录默认值</dd></div>'}</dl><div class="saved-negative"><span>描述</span><p>${esc(d.prompt||'未填写')}</p></div><p class="panel-note">内置素材用于演示结果区，不反映这些参数的生成效果。</p><div class="dialog-actions">${B('用这些参数重新编辑','reedit','button primary',`data-job="${id}"`)}</div>`,'small-dialog');return;}modal('本次生成参数',`<p class="settings-context">${esc(w?.name||getModel(d).name)}</p><dl class="parameter-summary"><div><dt>画面</dt><dd>${d.ratio} · ${d.quality}</dd></div><div><dt>${d.type==='video'?'时长':'数量'}</dt><dd>${d.type==='video'?d.duration:d.count+' 张'}</dd></div></dl><div class="saved-negative"><span>反向提示词</span><p>${esc(d.negative||'未设置')}</p></div><div class="dialog-actions">${B('用这些参数重新编辑','reedit','button primary',`data-job="${id}"`)}</div>`,'small-dialog');}
document.addEventListener('click',e=>{const choice=e.target.closest('[data-advanced-choice]');if(choice)setAdvanced(choice.dataset.advancedChoice,choice.dataset.value);});
document.addEventListener('input',e=>{if(e.target.matches('[data-advanced]'))setAdvanced(e.target.dataset.advanced,Number(e.target.value));});

// Real workflow bridge. UI layout and reusable asset storage remain in app.js.
function liveWorkflow(s=active()){const w=workflow(s);return w?.live?w:null;}
function qualityName(value){return ({0.2:'预览',0.5:'标准',1:'精细'})[value]||'自定义';}
function segmentOptions(label,items,value,attrs){return `<section class="picture-section"><h3>${label}</h3><div class="segmented-options">${items.map(([v,text])=>`<button class="segment ${String(value)===String(v)?'selected':''}" ${attrs} data-value="${v}" aria-pressed="${String(value)===String(v)}">${text}</button>`).join('')}</div></section>`;}
function pictureOptions(ratios,value,attrs){return segmentOptions('选择比例',ratios.map(v=>{const[a,b]=v.split(':').map(Number);return[v,`<span class="ratio-symbol" aria-hidden="true" style="width:${Math.round(a>=b?16:16*a/b)}px;height:${Math.round(b>=a?16:16*b/a)}px"></span><span>${v}</span>`]}),value,attrs);}
function livePicture(w,v){return workflowPicturePanel(w,active().draft,v);}
function estimatedSize(v){const[a,b]=v.ratio.split(':').map(Number),pixels=v.megapixels*1024*1024;return Math.round(Math.sqrt(pixels*a/b)/32)*32+' × '+Math.round(Math.sqrt(pixels*b/a)/32)*32;}
document.addEventListener('click',e=>{const choice=e.target.closest('[data-live-choice]');if(!choice)return;const w=liveWorkflow(),f=w?.fields.find(f=>f.key===choice.dataset.liveChoice);if(!f)return;const kind=f.key==='ref_size'?'reference-size':'picture';liveSettings(active().draft,w)[f.key]=typeof f.default==='number'?Number(choice.dataset.value):choice.dataset.value;const root=choice.closest('.workflow-inline-controls');if(root){const current=liveSettings(active().draft,w)[f.key];root.querySelectorAll('[data-live-choice]').forEach(b=>{if(b.dataset.liveChoice===f.key){const on=String(current)===b.dataset.value;b.setAttribute('aria-pressed',String(on));b.classList.toggle('selected',on);}});const input=root.querySelector('[data-live-field="'+f.key+'"]');if(input)input.value=current;}else{refreshComposer();liveIntent(document.querySelector(`[data-popup="${kind}"]`));}scheduleSave();});
function liveSettings(d,w){d.liveSettings||={};for(const f of w.fields)if(d.liveSettings[f.key]===undefined)d.liveSettings[f.key]=f.default;return d.liveSettings;}
function liveProblem(d,w,required=false){const refs=d.refs||[];if(refs.some(r=>r.available===false))return '原素材文件已被移除。请移除缺失项并重新导入同一份素材。';if(refs.some(r=>!['image','video'].includes(r.kind)))return '这两个工作流只接收图片和 MP4 视频。';for(const[k,lo,hi]of[['image','minImages','maxImages'],['video','minVideos','maxVideos']]){const n=refs.filter(r=>r.kind===k).length;if(n>w[hi]||required&&n<w[lo])return `${w.name}需要 ${w[lo]}–${w[hi]} 份${k==='image'?'图片':'视频'}素材。`;}return '';}
function liveComposer(s,w){const d=s.draft;d.type='video';d.mode='全能参考';const v=liveSettings(d,w),hasJobs=s.jobs.length;return `<section class="composer glass" aria-label="创作操作区"><div class="workflow-strip"><a class="control small-button" href="#workflows">${I('back')}工作流</a><span>${w.name}</span></div>${refsMarkup(d)}<div class="writing-row"><div class="writing-area"><label for="prompt" class="sr-only">镜头描述</label><textarea id="prompt" spellcheck="false" maxlength="6000" placeholder="${esc(w.placeholder)}" rows="${hasJobs?3:5}">${esc(d.prompt)}</textarea></div><button class="expand-writing icon-button" data-action="expand" aria-label="展开描述编辑区">${I('expand')}</button></div>${issueHTML(d)}<div class="composer-controls"><div class="control-cluster">${!d.refs.length?uploadControl(d):''}<button class="intent-control" data-popup="picture">${w.id==='h3-reference'?`${v.ratio} · ${qualityName(v.megapixels)}`:`原片比例 · ${v.long_side} px`}${I('down')}</button><button class="intent-control duration-control" data-popup="output" aria-label="视频时长">${I('clock')}${w.id==='h3-reference'?'约':'前'} ${v.duration} 秒</button><button class="intent-control extra-control" data-popup="more" aria-label="高级设置">${I('settings')}<span>高级</span></button></div><button class="button primary generate" data-action="generate" ${s.liveSubmitting?'disabled':''}>${I('spark')}${s.liveSubmitting?'正在提交…':'生成 · 算力卡计费'} ${I('arrow')}</button></div></section><div class="composer-foot"><span>${!hasJobs?B('填入一段示例','example','text-control'):''}</span><span>费用按当前卡计时，本站不收积分</span></div><div class="composer-utilities">${B(I('folder')+'素材库','open-assets','text-control')}${B(I('checklist')+'批量提示词','batch-prompts','text-control')}</div>`;}
function liveField(f,v){const name='live-'+f.key;return `<label class="live-field" for="${name}"><span>${esc(f.label)}</span>${f.options?`<select id="${name}" data-live-field="${f.key}">${f.options.map(o=>`<option value="${o}" ${String(v)===String(o)?'selected':''}>${f.key==='steps'?o+' 步':({match:'适配画面',max:'完整参考'})[o]||o}</option>`).join('')}</select>`:`<input id="${name}" data-live-field="${f.key}" required type="number" ${f.key==='seed'?'title="填 -1 使用随机值；填写固定整数用于复现"':''} min="${f.min}" max="${f.max}" step="${f.step}" value="${v}">`}</label>`;}
function liveIntent(el){if(!el)return;const w=liveWorkflow(),d=active().draft,v=liveSettings(d,w),kind=el.dataset.popup;if(kind==='seed'){const mode=d.liveSeedMode||(v.seed<0?'random':'fixed');popup(el,'随机种子',`<div class="seed-setting"><div class="wf-options" role="group" aria-label="随机种子模式"><button data-live-seed-mode="random" aria-pressed="${mode==='random'}">每次随机</button><button data-live-seed-mode="fixed" aria-pressed="${mode==='fixed'}">固定种子</button></div>${mode==='fixed'?liveField({...w.fields.find(f=>f.key==='seed'),min:0},v.seed):''}</div>`);panel.classList.add('advanced-popup');return;}if(kind==='reference-size'){popup(el,'',referenceSizePanel(w,d,v));panel.classList.add('picture-popup');positionPanel(el);return;}if(kind==='picture'){popup(el,'',livePicture(w,v));panel.classList.add('picture-popup');positionPanel(el);return;}if(kind==='output'){const f=w.fields.find(f=>f.key==='duration');popup(el,'',`<div class="duration-panel"><div class="duration-readout"><span>${w.id==='bernini-edit'?'处理片段时长':'视频时长'}</span><strong><output id="live-duration-value">${v.duration}</output><small>秒</small></strong></div><input data-live-field="duration" id="live-duration" aria-label="视频时长" type="range" min="${f.min}" max="${f.max}" step="${f.step}" value="${v.duration}" style="--range-progress:${(v.duration-f.min)/(f.max-f.min)*100}%"><div class="duration-ends"><span>${f.min} 秒</span><span>${f.max} 秒</span></div></div>`);panel.classList.add('duration-popup');return;}
const keys=kind==='picture'?(w.id==='h3-reference'?['ratio','megapixels']:['long_side']):[];
const neg=kind==='more'&&w.negative?`<section class="advanced-negative"><label class="intent-label" for="negative">反向提示词 <span>可选</span></label><textarea id="negative" class="negative-input" placeholder="写下要避免的元素，如：水印、画面闪烁" rows="3">${esc(d.negative||'')}</textarea></section>`:'';
popup(el,kind==='picture'?'画面设置':'高级设置',`${neg}<div class="live-fields">${w.fields.filter(f=>keys.includes(f.key)).map(f=>liveField(f,v[f.key])).join('')}</div><p class="live-form-status" role="alert"></p><div class="advanced-footer">${B('恢复默认','live-reset','text-control')}${B('完成','close-panel','button primary')}</div>`);panel.classList.add('advanced-popup');}
async function liveApi(path,options){if(publicPreview)throw new Error('公开预览不连接算力卡，请使用获授权的私有入口。');const r=await fetch(path,options);let data;try{data=await r.json();}catch{throw new Error('本地服务没有返回有效响应，请重新启动 MVP 服务。');}if(!r.ok){const e=new Error(typeof data.detail==='string'?data.detail:'参数格式不正确，请检查后重试。');e.httpStatus=r.status;throw e;}return data;}
const liveJson=value=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});
function liveJobStatus(j){if(j.status==='failed')return `<div class="task-failure"><strong>生成未完成</strong><p>${esc(j.error||'执行失败，请检查素材后重试。')}</p>${B('修改后重试','reedit','small-button',`data-job="${j.id}"`)}${B('重试 · 算力卡计费','retry','small-button primary',`data-job="${j.id}"`)}</div>`;if(j.status==='abandoned')return '<div class="cancelled-task">已停止本地等待 · 远端可能仍运行，请在算力卡端确认。</div>';if(j.status==='cancelled')return '<div class="cancelled-task">任务已取消 · 已用费用不退</div>';return `<div class="task-progress real-task"><div class="progress-line"><span class="live-dot"></span><strong>${esc(j.serverStatus==='cancelling'?'正在取消…':j.serverStatus==='running'?'生成中':(j.stage||'正在上传素材').split(' · 当前步骤')[0])}</strong><span class="elapsed">已等待 <time>${formatTime(Date.now()-j.started)}</time></span>${B(j.serverStatus==='cancelling'||j.cancelRequested?'正在取消…':'取消任务','cancel','small-button',`data-job="${j.id}" ${j.serverStatus==='cancelling'||j.cancelRequested?'disabled':''}`)}</div><div class="progress-track indeterminate" aria-hidden="true"><span></span></div>${j.cancelError||j.connection_error||j.error?`<p class="live-connection">${esc(j.cancelError||j.connection_error||j.error)}</p>`:''}${j.cancelPersisted?B('停止本地等待','abandon-live','text-control',`data-job="${j.id}"`):''}</div>`;}
function mergeCatalogJob(j,r){const previous=new Map((j.outputs||[]).map(o=>[o.id,o])),w=workflows.find(w=>w.id===r.workflow_id);Object.assign(j,{real:true,remoteId:r.id,serverStatus:r.status,cancelError:r.cancel_error,cancelPersisted:!!r.cancel_requested,status:['done','failed','cancelled','abandoned'].includes(r.status)?r.status:'running',stage:r.stage,progress:null,error:r.error,connection_error:r.connection_error,started:r.started,ended:r.ended,promptId:r.prompt_id,outputs:(r.outputs||[]).map(o=>({...previous.get(o.id),...o}))});j.snapshot={...j.snapshot,catalogLive:true,catalogDemo:false,type:w?.output==='video'?'video':'image',workflowId:r.workflow_id,prompt:r.prompt,negative:r.negative,catalogValues:{...(j.snapshot?.catalogValues||{}),...catalogValuesFromSettings(w,r.settings)}};if(!j.snapshot.refs?.length&&r.references?.length){const counts={image:0,video:0,audio:0};j.snapshot.refs=r.references.map((a,i)=>({id:(a.kind==='video'?'视频':a.kind==='audio'?'音频':'图片')+(++counts[a.kind]),kind:a.kind,name:a.name,src:a.src,serverAssetId:a.id,catalogSlot:w?.interface?.media?.[i]?.id,available:a.available}));}}
function mergeLiveJob(j,r){if(workflows.find(w=>w.id===r.workflow_id)?.catalogConnected)return mergeCatalogJob(j,r);const previous=new Map((j.outputs||[]).map(o=>[o.id,o]));Object.assign(j,{real:true,remoteId:r.id,serverStatus:r.status,cancelError:r.cancel_error,cancelPersisted:!!r.cancel_requested,status:['done','failed','cancelled','abandoned'].includes(r.status)?r.status:'running',stage:r.stage,progress:null,error:r.error,connection_error:r.connection_error,started:r.started,ended:r.ended,promptId:r.prompt_id,outputs:(r.outputs||[]).map(o=>({...previous.get(o.id),...o}))});const counts={image:0,video:0};j.snapshot={...j.snapshot,type:'video',mode:'全能参考',prompt:r.prompt.replace(/(?<!@)(图片|视频)\d+/g,t=>'@'+t),negative:r.negative,liveSettings:{...r.settings},workflowId:r.workflow_id,ratio:r.settings.ratio||'原片比例',quality:r.settings.megapixels?qualityName(r.settings.megapixels):r.settings.long_side+' px',duration:'约 '+r.settings.duration+' 秒'};if(r.references)j.snapshot.refs=r.references.map(a=>({id:(a.kind==='image'?'图片':'视频')+(++counts[a.kind]),serverAssetId:a.id,kind:a.kind,name:a.name,src:a.src,available:a.available}));}
async function rerunLive(original,session,button){if(original.rerunning||!original.remoteId)return;original.rerunning=true;if(button)button.disabled=true;const j={id:'live-'+crypto.randomUUID(),real:true,outputs:[],snapshot:cloneDraft(original.snapshot),cost:null,started:Date.now(),status:'running',stage:'正在提交到算力卡',token:crypto.randomUUID()};session.jobs.push(j);refreshFeed(true);scheduleSave();try{mergeLiveJob(j,await liveApi('/api/jobs/'+original.remoteId+'/rerun',liveJson({token:j.token})));toast('已按原输入提交，仅更换随机种子');}catch(e){if(e.httpStatus){j.status='failed';j.error=e.message;j.ended=Date.now();}else{j.status='running';j.submissionUncertain=true;j.error='连接中断，正在找回这次提交，请勿重复提交。';}}finally{original.rerunning=false;if(button)button.disabled=false;refreshFeed();sidebar();scheduleSave();}}
async function submitLive(snapshot,session=active(),retryJob){if(session.liveSubmitting)return false;const w=liveWorkflow(session),base=snapshot||session.draft,d={...renumberDraftReferences(cloneDraft(base)),liveSettings:{...liveSettings(base,w)},workflowId:w.id};if(hasRemovedReference(d.prompt)){inlineError('描述中有已移除的素材引用，请先修改。','refs');return false;}const problem=liveProblem(d,w,true);if(problem){inlineError(problem,'refs-library');return false;}if(!d.prompt.trim()){inlineError('写下要生成或修改的画面，例如主体动作与镜头运动。','example');return false;}const missing=(d.prompt.match(/@(图片|视频|音频)\d+/g)||[]).filter(t=>!d.refs.some(r=>'@'+r.id===t));if(missing.length){inlineError(missing.join('、')+' 没有对应素材。','refs');return false;}
const j={id:'live-'+crypto.randomUUID(),real:true,outputs:[],snapshot:d,cost:null,started:Date.now(),status:'running',stage:'正在上传素材',token:crypto.randomUUID()};session.jobs.push(j);session.title=d.prompt.slice(0,28);session.liveSubmitting=true;session.draft.error=null;state.active=session.id;closePanel();render();scheduleSave();
try{const asset_ids=[];for(const [i,ref] of d.refs.entries()){if(j.cancelRequested){j.status='cancelled';j.ended=Date.now();return false;}if(ref.serverAssetId){asset_ids.push(ref.serverAssetId);continue;}j.stage=`正在上传素材 ${i+1} / ${d.refs.length}`;refreshFeed();const a=workspace.assets.find(a=>a.id===ref.assetId),blob=a?.blob||await fetch(ref.src).then(r=>{if(!r.ok)throw new Error('无法读取参考素材，请重新导入。');return r.blob();});const form=new FormData();form.append('file',blob,(ref.name||'素材').replace(/\.[^.]+$/,'')+(ref.kind==='video'?'.mp4':blob.type==='image/png'?'.png':blob.type==='image/webp'?'.webp':'.jpg'));const uploaded=await liveApi('/api/assets',{method:'POST',body:form});asset_ids.push(uploaded.id);}
if(j.cancelRequested){j.status='cancelled';j.ended=Date.now();return false;}let imageNo=0,videoNo=0;const mapping=new Map(d.refs.map(ref=>['@'+ref.id,ref.kind==='image'?'图片'+(++imageNo):'视频'+(++videoNo)]));const prompt=d.prompt.replace(/@(图片|视频|音频)\d+/g,t=>mapping.get(t)||t);j.stage='正在提交到算力卡';refreshFeed();
const response=await liveApi('/api/jobs',liveJson({workflow_id:w.id,prompt,negative:w.negative?d.negative||'':'',settings:{...d.liveSettings,seed:d.liveSeedMode==='random'?-1:d.liveSettings.seed},asset_ids,token:j.token}));mergeLiveJob(j,response);if(j.cancelRequested)await cancelLive(j);
}catch(e){j.status='failed';j.error=e.message;j.ended=Date.now();if(j.stage==='正在提交到算力卡'){j.status='running';j.stage='正在确认提交状态';j.submissionUncertain=true;j.error='本地连接中断，正在找回任务，请勿重复提交。';}}
finally{session.liveSubmitting=false;refreshComposer();refreshFeed();sidebar();scheduleSave();}return true;}
let livePollBusy=false;
async function syncLiveJobs(){if(publicPreview||!production||!liveCatalog.length||livePollBusy)return;livePollBusy=true;try{const list=await liveApi('/api/jobs');let changed=false;for(const r of list){let found;for(const s of state.sessions){const j=s.jobs.find(j=>j.remoteId===r.id||j.token&&j.token===r.request_token);if(j){found={s,j};break;}}
if(!found){const w=workflows.find(w=>w.id===r.workflow_id),catalog=!!w?.catalogConnected,type=catalog?(w.output==='video'?'video':'image'):'video',catalogValues=catalog?catalogValuesFromSettings(w,r.settings):null;let s=state.sessions.findLast(s=>s.scope==='wf:'+r.workflow_id);if(!s){s={id:'s'+nextSession++,scope:'wf:'+r.workflow_id,title:r.prompt.slice(0,28),draft:{...newDraft(type),prompt:r.prompt,...(catalog?{catalogValues}:{liveSettings:r.settings})},jobs:[]};state.sessions.push(s);}const j={id:'live-'+r.id,real:true,snapshot:{...newDraft(type),prompt:r.prompt,negative:r.negative,workflowId:r.workflow_id,...(catalog?{catalogLive:true,catalogValues}:{liveSettings:r.settings})},outputs:[]};s.jobs.push(j);found={s,j};changed=true;}
const j=found.j,before=JSON.stringify([j.status,j.stage,j.progress,j.error,j.connection_error,j.cancelError,j.cancelPersisted,j.outputs,j.ended]);mergeLiveJob(j,r);if(j.cancelRequested&&j.remoteId&&j.status==='running'&&j.serverStatus!=='cancelling'){j.cancelRequested=false;await cancelLive(j);}if(JSON.stringify([j.status,j.stage,j.progress,j.error,j.connection_error,j.cancelError,j.cancelPersisted,j.outputs,j.ended])!==before)changed=true;}
for(const s of state.sessions)for(const j of s.jobs){if(j.real&&j.status==='running'&&!j.remoteId&&Date.now()-j.started>90000&&!list.some(r=>r.request_token===j.token)){j.stage='正在确认提交记录';j.error='暂未查到提交记录，请检查算力卡队列后再试，避免重复生成。';changed=true;}}if(changed){scheduleSave();sidebar();if($('#result-feed'))refreshFeed();else if(!dialog.open&&route().name==='library')refreshLibrary();}
}catch{for(const s of state.sessions)for(const j of s.jobs)if(j.real&&j.status==='running'){j.connection_error='本地服务暂时不可达，恢复后会继续查询。';}if($('#result-feed'))refreshFeed();}finally{livePollBusy=false;}}
async function cancelLive(j){if(!j.remoteId){j.cancelRequested=true;j.stage='正在取消…';refreshFeed();scheduleSave();return;}try{mergeLiveJob(j,await liveApi('/api/jobs/'+j.remoteId+'/cancel',{method:'POST'}));j.cancelRequested=false;refreshFeed();scheduleSave();}catch(e){toast(e.message);}}
