let lastRemovedWorkIds=[];
async function removeWorks(ids){
 const eligible=allOutputs().filter(({o})=>ids.includes(o.id)&&!o.removedAt).map(({o})=>o.id);if(!eligible.length)return;
 const confirmed=await confirmAction({title:eligible.length===1?'移除这件作品？':`移除 ${eligible.length} 件作品？`,message:'移除后可在「已移除」中恢复，原素材与历史输入保留。',label:eligible.length===1?'移除作品':'批量移除'});if(!confirmed)return;
 const changed=removeOutputs(allOutputs(),eligible);if(!changed.length)return;
 lastRemovedWorkIds=changed;changed.forEach(id=>{state.selected.delete(id);workspace.workSelected.delete(id);});
 if(dialog.open)dialog.close();scheduleSave();if(route().name==='library')refreshLibrary();else if($('#result-feed'))refreshFeed();
 if(route().name==='library')syncWorkSelection();else syncSelection();
 const notice=$('#toast');notice.innerHTML=`<span>已移除 ${changed.length} 件作品</span><button type="button" data-action="undo-remove-works">撤销</button>`;notice.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.classList.remove('show'),8000);
}
function restoreWorks(ids){
 const changed=restoreOutputs(allOutputs(),ids);if(!changed.length)return;scheduleSave();
 if(dialog.matches('.removed-works-dialog')&&dialog.open)showRemovedWorks();
 if(route().name==='library'){if(!dialog.open)refreshLibrary();syncWorkSelection();}else if($('#result-feed'))refreshFeed();toast(`已恢复 ${changed.length} 件作品。`);
}
function showRemovedWorks(){
 const rows=allOutputs().filter(({o})=>o.removedAt).sort((a,b)=>b.o.removedAt-a.o.removedAt);
 modal('已移除的作品',`${rows.length?`<div class="removed-works-list">${rows.map(({o,j})=>`<div>${o.type==='image'?`<img src="${esc(o.src)}" alt="">`:`<video src="${esc(o.src)}" muted preload="metadata"></video>`}<span><strong>${esc(workTitle(j,o))}</strong><small>${new Date(o.removedAt).toLocaleString('zh-CN')}</small></span>${B('恢复','restore-work','small-button',`data-id="${esc(o.id)}"`)}</div>`).join('')}</div><div class="dialog-actions">${B('全部恢复','restore-all-works','button primary')}</div>`:'<p class="panel-note">没有已移除的作品。</p>'}`,'small-dialog removed-works-dialog');
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="undo-remove-works"]'))restoreWorks(lastRemovedWorkIds);});

const outputSaves=new Set();
async function saveOutputAsset(id,button){
 const found=findOutput(id);if(!found||outputSaves.has(id))return;outputSaves.add(id);button.disabled=true;
 try{
  const response=await fetch(found.o.src);if(!response.ok)throw new Error('无法读取作品文件');const blob=await response.blob();
  const mime=blob.type.startsWith(found.o.type+'/')?blob.type:found.o.type==='video'?'video/mp4':'image/png',extension=({'video/mp4':'mp4','video/webm':'webm','image/png':'png','image/jpeg':'jpg','image/webp':'webp'})[mime]|| (found.o.type==='video'?'mp4':'png');
  const added=await importAssets([new File([blob],workTitle(found.j,found.o)+'.'+extension,{type:mime})]);if(!added.length)throw new Error('素材保存失败');
  if(added[0].hidden){added[0].hidden=false;await putAsset(added[0]);}
  toast(found.o.type==='video'?'视频已保存到素材库。':'图片已保存到素材库。');
 }catch(e){toast('保存失败：'+e.message+'，可重试。');}finally{outputSaves.delete(id);if(button.isConnected)button.disabled=false;}
}
